const ETHICS_QUESTIONS = [
  { domain: "Professional Orientation & Ethics", question: "Frank Parsons is credited with founding the counseling profession through his pioneering work in which area?", options: ["A) Psychoanalytic therapy", "B) Vocational guidance", "C) Group counseling", "D) School-based counseling"], correct: 1, explanation: "Frank Parsons developed vocational guidance in the early 1900s, establishing the foundational concepts that led to the modern counseling profession. His work with youth and job placement created the framework for counselor-client relationships." },
  { domain: "Professional Orientation & Ethics", question: "Jesse Davis is recognized for introducing counseling into which institutional setting during the early 20th century?", options: ["A) Mental hospitals", "B) Private practice clinics", "C) Public schools", "D) University counseling centers"], correct: 2, explanation: "Jesse Davis brought counseling into public schools around 1907, establishing the first systematic school counseling program. This was a major milestone in making counseling accessible to students in educational settings." },
  { domain: "Professional Orientation & Ethics", question: "Clifford Beers' work in mental health reform was significant because he advocated for which of the following?", options: ["A) Strict confidentiality in all therapeutic relationships", "B) Humane treatment of people with mental illness", "C) Mandatory licensing of all counselors", "D) Exclusive use of psychoanalytic methods"], correct: 1, explanation: "Clifford Beers, a mental health advocate, championed the mental hygiene movement and advocated for humane, ethical treatment of individuals with mental illness. His work influenced standards of care and professionalization." },
  { domain: "Professional Orientation & Ethics", question: "Carl Rogers' contributions to counseling ethics include emphasizing which of these core conditions?", options: ["A) Diagnosis, assessment, and intervention planning", "B) Unconditional positive regard, empathy, and congruence", "C) Transference analysis and dream interpretation", "D) Behavioral reinforcement and contingency management"], correct: 1, explanation: "Carl Rogers emphasized core conditions for therapeutic effectiveness: unconditional positive regard, genuine empathy, and counselor congruence. These concepts remain central to ethical counseling practice." },
  { domain: "Professional Orientation & Ethics", question: "Gilbert Wrenn's concept of 'cultural encapsulation' refers to which counselor limitation?", options: ["A) Inability to work with diverse populations due to limited cultural awareness", "B) Exclusion from professional counseling organizations", "C) Failure to maintain appropriate boundaries with clients", "D) Insufficient understanding of diagnostic criteria"], correct: 0, explanation: "Cultural encapsulation describes counselors' tendency to be limited by their own cultural assumptions and unable to recognize clients' differing worldviews. This concept emphasized the need for multicultural competence." },
  { domain: "Professional Orientation & Ethics", question: "Robert Carkhuff's model of counselor training emphasized which primary skill development?", options: ["A) Accurate diagnosis of mental disorders", "B) Systematic teaching of core communication and helping skills", "C) Extensive knowledge of psychopharmacology", "D) Mastery of multiple theoretical orientations"], correct: 1, explanation: "Carkhuff developed systematic models for training counselors in core helping skills, such as empathy, respect, and concreteness. His approach made counselor training more structured and measurable." },
  { domain: "Professional Orientation & Ethics", question: "CACREP accreditation differs from individual counselor certification in that it primarily evaluates which entity?", options: ["A) Individual counselor competency and knowledge", "B) Counseling graduate programs and their curriculum", "C) Insurance company reimbursement policies", "D) State licensing board requirements"], correct: 1, explanation: "CACREP (Council for Accreditation of Counseling and Related Educational Programs) accredits graduate counseling programs, while certification evaluates individual counselor competence. Accreditation focuses on program quality." },
  { domain: "Professional Orientation & Ethics", question: "Licensure differs from certification in that licensure is typically a requirement for which of the following?", options: ["A) Publishing research in peer-reviewed journals", "B) Legal permission to practice counseling independently", "C) Membership in professional counseling associations", "D) Completion of a master's degree program"], correct: 1, explanation: "Licensure is a legal credential granted by states that provides legal authority to practice independently and claim the title 'licensed counselor.' Certification is a voluntary credential indicating competency in a specialty area." },
  { domain: "Professional Orientation & Ethics", question: "According to the ACA Code of Ethics (2014), which principle represents the counselor's obligation to respect client autonomy?", options: ["A) Beneficence", "B) Nonmaleficence", "C) Autonomy", "D) Justice"], correct: 2, explanation: "Autonomy is the ethical principle emphasizing respect for clients' right to self-determination and decision-making. It underlies informed consent and the ethical obligation to protect clients' freedom of choice." },
  { domain: "Professional Orientation & Ethics", question: "Which ACA ethical principle obligates counselors to refrain from harming clients through their professional actions?", options: ["A) Beneficence", "B) Nonmaleficence", "C) Fidelity", "D) Justice"], correct: 1, explanation: "Nonmaleficence is the ethical principle requiring counselors to 'do no harm.' It guides counselors to avoid actions that could hurt clients and to recognize risks in treatment." },
  { domain: "Professional Orientation & Ethics", question: "The ACA Code of Ethics requires counselors to respect client confidentiality with which important exception?", options: ["A) When a client is in danger of harming themselves or others", "B) When the counselor needs to discuss the case with colleagues", "C) When the client requests a second opinion from another counselor", "D) When insurance companies request detailed clinical notes"], correct: 0, explanation: "Confidentiality has a critical exception when there is imminent danger of serious harm to the client or others. Counselors are ethically and legally required to breach confidentiality to protect safety." },
  { domain: "Professional Orientation & Ethics", question: "A dual relationship in counseling most directly violates which ethical principle?", options: ["A) The principle of beneficence", "B) The principle of fidelity and boundary maintenance", "C) The principle of autonomy", "D) The principle of justice"], correct: 1, explanation: "Dual relationships (such as counseling a friend or family member) compromise professional boundaries and fidelity. They create conflicts of interest that can impair clinical judgment and harm the client." },
  { domain: "Professional Orientation & Ethics", question: "According to the ACA Code of Ethics, informed consent requires counselors to disclose which information to clients?", options: ["A) Only the counselor's theoretical orientation", "B) Relevant qualifications, limits of confidentiality, fees, and procedures used", "C) The counselor's personal therapy history", "D) Diagnoses of all previous clients with similar presentations"], correct: 1, explanation: "Informed consent requires disclosure of counselor qualifications, confidentiality limits, fees, procedures, risks/benefits, and the client's rights. This enables clients to make autonomous decisions about treatment." },
  { domain: "Professional Orientation & Ethics", question: "Which court case established the principle of privileged communication in counseling relationships?", options: ["A) Tarasoff v. Regents of University of California", "B) Jaffee v. Redmond", "C) Miranda v. Arizona", "D) Roe v. Wade"], correct: 1, explanation: "Jaffee v. Redmond established psychotherapist-patient privilege in federal court, protecting client communications from mandatory disclosure. This landmark case elevated counseling to the same privilege level as attorney-client relationships." },
  { domain: "Professional Orientation & Ethics", question: "The Tarasoff decision requires mental health professionals to do which of the following when a client poses danger?", options: ["A) Maintain complete confidentiality regardless of circumstances", "B) Warn the potential victim and notify appropriate authorities", "C) Immediately terminate treatment with the client", "D) Only inform the client's insurance company"], correct: 1, explanation: "Tarasoff established the 'duty to warn' requiring therapists to take reasonable steps to protect identifiable victims. This duty to protect outweighs the normal duty of confidentiality when serious danger exists." },
  { domain: "Professional Orientation & Ethics", question: "Which federal law specifically protects student educational records from unauthorized disclosure?", options: ["A) HIPAA", "B) FERPA", "C) ADA", "D) IDEA"], correct: 1, explanation: "FERPA (Family Educational Rights and Privacy Act) protects student education records and restricts disclosure without parental consent (for minors) or student consent (for adults). School counselors must comply with FERPA." },
  { domain: "Professional Orientation & Ethics", question: "HIPAA primarily applies to which entities in the healthcare system?", options: ["A) All licensed mental health professionals regardless of setting", "B) Covered entities that handle protected health information electronically", "C) Only psychiatrists in hospital settings", "D) All school-based counselors"], correct: 1, explanation: "HIPAA (Health Insurance Portability and Accountability Act) applies to covered entities and business associates handling protected health information. Counselors in private practice and some community mental health settings must comply." },
  { domain: "Professional Orientation & Ethics", question: "The IDEA (Individuals with Disabilities Education Act) ensures which primary right for students with disabilities?", options: ["A) Free and appropriate education in the least restrictive environment", "B) Guaranteed private mental health services", "C) Automatic accommodation of all learning differences", "D) Complete exemption from standardized testing"], correct: 0, explanation: "IDEA mandates that students with disabilities receive a free and appropriate public education in the least restrictive environment. It requires individualized education plans (IEPs) and appropriate accommodations." },
  { domain: "Professional Orientation & Ethics", question: "Section 504 of the Rehabilitation Act differs from IDEA in that it applies to which group?", options: ["A) Only students diagnosed with autism spectrum disorder", "B) Any student with a disability affecting major life activities, not just school-eligible students", "C) Exclusively adult individuals in vocational rehabilitation programs", "D) Only students receiving special education services"], correct: 1, explanation: "Section 504 applies more broadly than IDEA, protecting any individual with a disability that substantially limits a major life activity. Counselors must ensure 504 accommodations are implemented for eligible students." },
  { domain: "Professional Orientation & Ethics", question: "The ADA (Americans with Disabilities Act) requires counselors and counseling agencies to provide which accommodation?", options: ["A) Free unlimited sessions to all clients with disabilities", "B) Automatic modification of treatment approaches regardless of effectiveness", "C) Reasonable accommodations that enable individuals with disabilities to access services", "D) Acceptance of all clients regardless of counselor competence in their areas of need"], correct: 2, explanation: "The ADA requires reasonable accommodations—modifications that enable access without fundamentally altering services. Examples include interpreter services, accessible facilities, and alternative communication formats." },
  { domain: "Professional Orientation & Ethics", question: "Which organization awards the National Counselor Certification (NCC)?", options: ["A) American Counseling Association (ACA)", "B) Council for Accreditation of Counseling and Related Educational Programs (CACREP)", "C) National Board for Certified Counselors (NBCC)", "D) American Mental Health Counselors Association (AMHCA)"], correct: 2, explanation: "The NBCC administers the National Counselor Examination and awards the NCC credential. This is the primary national certification for counselors and is recognized across states." },
  { domain: "Professional Orientation & Ethics", question: "Typical requirements for LPC (Licensed Professional Counselor) licensure include all of the following EXCEPT:", options: ["A) Completion of a master's degree in counseling", "B) A specified number of supervised clinical hours", "C) Passing a state licensure examination", "D) Completion of a doctoral degree in psychology"], correct: 3, explanation: "LPC licensure typically requires a master's degree, 2,000-4,000 supervised hours (varies by state), and passing the NCE or state exam. A doctoral degree is not required for initial licensure." },
  { domain: "Professional Orientation & Ethics", question: "Which credential specifically certifies counselors' competence in school counseling?", options: ["A) NCC (National Counselor Certification)", "B) CCMHC (Certified Clinical Mental Health Counselor)", "C) NCSC (National Certified School Counselor)", "D) LMHC (Licensed Mental Health Counselor)"], correct: 2, explanation: "The NCSC (National Certified School Counselor) credential, administered by NBCC, certifies school counselors' knowledge and competence. It's the specialty certification specific to school counseling." },
  { domain: "Professional Orientation & Ethics", question: "Counselor impairment due to substance abuse, mental illness, or personal crisis is addressed in the ACA Code of Ethics under which section?", options: ["A) Confidentiality and privacy section", "B) Assessment and diagnosis section", "C) The counselor wellness and self-care provisions", "D) Professional competence and integrity section"], correct: 3, explanation: "The ACA Code of Ethics addresses counselor impairment under professional competence and integrity, requiring counselors to recognize when personal issues may impair practice and to seek help." },
  { domain: "Professional Orientation & Ethics", question: "Which of the following is most consistent with ethical self-care and wellness practices for counselors?", options: ["A) Exclusively discussing personal issues in individual therapy", "B) Avoiding any discussion of personal challenges with colleagues", "C) Regular participation in supervision, personal therapy, and wellness activities", "D) Restricting professional practice to avoid stress"], correct: 2, explanation: "Ethical self-care includes ongoing supervision, personal therapy, exercise, healthy relationships, and wellness practices. These sustain counselor well-being and prevent burnout and impairment." },
  { domain: "Professional Orientation & Ethics", question: "The ACA Code of Ethics includes advocacy competencies, which obligate counselors to do which of the following?", options: ["A) Advocate exclusively for individual clients in therapy", "B) Engage in social justice work to remove systemic barriers affecting clients", "C) Avoid political involvement to maintain neutrality", "D) Only advocate when directly requested by clients"], correct: 1, explanation: "Advocacy competencies require counselors to work toward systemic change and social justice, removing barriers that affect clients' well-being. This includes advocacy at community, institutional, and societal levels." },
  { domain: "Professional Orientation & Ethics", question: "Managed care and third-party reimbursement create ethical challenges for counselors primarily because they:", options: ["A) Require ongoing professional development", "B) May limit client access to services or require treatment limitations that conflict with client needs", "C) Necessitate detailed case notes", "D) Prevent counselors from specializing"], correct: 1, explanation: "Managed care creates ethical tensions by imposing session limits, requiring diagnosis for coverage, and potentially prioritizing cost over care. Counselors must advocate for clients while navigating these constraints." },
  { domain: "Professional Orientation & Ethics", question: "The American Counseling Association (ACA) differs from the American Mental Health Counselors Association (AMHCA) in that AMHCA specifically represents which group?", options: ["A) All counseling professionals regardless of specialization", "B) School counselors and career counselors", "C) Mental health counselors in clinical practice settings", "D) Counseling educators and researchers only"], correct: 2, explanation: "AMHCA focuses specifically on mental health counseling and clinical practice, while ACA represents the broader counseling profession across all specializations. AMHCA members often work in community mental health, private practice." },
  { domain: "Professional Orientation & Ethics", question: "The American School Counselors Association (ASCA) primarily advocates for which professional practice area?", options: ["A) College and university counseling", "B) School counseling in K-12 settings", "C) Career development across all life stages", "D) Mental health crisis intervention"], correct: 1, explanation: "ASCA represents school counselors in K-12 settings, providing standards, advocacy, and professional development specific to school counseling practice and the school environment." },
  { domain: "Professional Orientation & Ethics", question: "Which professional organization focuses on counseling for marriage, couples, and family therapy?", options: ["A) International Association of Marriage and Family Counselors (IAMFC)", "B) International Association of Addiction and Offender Counselors (IAAOC)", "C) American Group Psychotherapy Association (AGPA)", "D) National Association of Addiction Treatment Providers (NAATP)"], correct: 0, explanation: "IAMFC is the ACA-affiliated organization for counselors specializing in couples and family counseling. It provides standards, training, and advocacy specific to marriage and family therapy." },
  { domain: "Professional Orientation & Ethics", question: "The Association for Specialists in Group Work (ASGW) develops ethical guidelines specific to which counseling modality?", options: ["A) Individual counseling only", "B) Career counseling and vocational guidance", "C) Group counseling and group therapy", "D) Substance abuse treatment exclusively"], correct: 2, explanation: "ASGW establishes ethical guidelines and best practices specific to group counseling and group therapy. These address unique ethical issues in group settings, such as confidentiality in groups." },
  { domain: "Professional Orientation & Ethics", question: "According to supervision ethics, a supervisor's primary responsibility is to ensure which outcome?", options: ["A) The supervisor's popularity and approachability", "B) The counselor supervisee's professional development and client welfare", "C) Compliance with all agency policies without exception", "D) Reduction of liability for the agency"], correct: 1, explanation: "Ethical supervision prioritizes supervisee development and client welfare. Supervisors assess competence, address deficiencies, and ensure ethical practice while supporting growth." },
  { domain: "Professional Orientation & Ethics", question: "The Discrimination Model of supervision (Bernard) emphasizes which supervisory approach?", options: ["A) Discriminating against supervisees based on weaknesses", "B) Teaching supervisees to discriminate between different client presentations", "C) Varying supervisor focus among three dimensions: interventions, conceptualization, and personalization", "D) Distinguishing between psychotic and non-psychotic clients"], correct: 2, explanation: "The Discrimination Model (Bernard) emphasizes varying supervisor focus across three dimensions (interventions, conceptualization, and personalization) and three roles (teacher, counselor, consultant) based on supervisee development." },
  { domain: "Professional Orientation & Ethics", question: "Developmental models of supervision posit that supervisees progress through predictable stages of competence and awareness. Which statement best describes this progression?", options: ["A) Supervisees maintain consistent competence throughout their careers", "B) Supervisees progress from high anxiety and low competence toward autonomy and confidence", "C) Supervisees regress in skill if they fail to advance", "D) Competence development is entirely unpredictable"], correct: 1, explanation: "Developmental models (like Stoltenberg's) describe progression from anxiety and dependency toward autonomy and integration. Early-career supervisees have higher anxiety and require more support; experienced supervisees need consultation rather than instruction." },
  { domain: "Professional Orientation & Ethics", question: "Interpersonal Process Recall (IPR) supervision involves which primary technique?", options: ["A) Role-playing client scenarios with the supervisor", "B) Reviewing recordings of counseling sessions and exploring the supervisor-supervisee interpersonal dynamics", "C) Paper-and-pencil assessment of diagnostic skills", "D) Requiring supervisees to present detailed case conceptualizations"], correct: 1, explanation: "IPR, developed by Kagan, involves reviewing recordings with an IPR facilitator to explore the supervisee's internal experience and interpersonal dynamics during sessions. This deepens self-awareness and skill." },
  { domain: "Professional Orientation & Ethics", question: "A counselor's scope of practice should be determined primarily by which factors?", options: ["A) Client requests and insurance coverage", "B) The counselor's personal interests and theoretical orientation", "C) Training, experience, supervision, and demonstrated competence", "D) The credentials the counselor holds"], correct: 2, explanation: "Scope of practice is ethically determined by training, experience, supervision received, and demonstrated competence—not by credentials alone or client requests. Counselors practice only within their competence." },
  { domain: "Professional Orientation & Ethics", question: "When a counselor recognizes that a client's needs exceed the counselor's competence, the ethical obligation is to:", options: ["A) Continue therapy while consulting with others", "B) Immediately terminate the relationship without referral", "C) Refer the client to an appropriate professional", "D) Encourage the client to lower their expectations"], correct: 2, explanation: "Ethical practice requires counselors to recognize competence limits and make appropriate referrals to qualified professionals. This honors clients' right to competent care and prevents harm." },
  { domain: "Professional Orientation & Ethics", question: "Regarding technology in counseling, the ACA Code of Ethics addresses which primary concern?", options: ["A) Prohibition of all online or technology-assisted counseling", "B) Requirements for informed consent, security, and competence when using technology", "C) Mandatory use of the latest technology for all counselors", "D) Permission to use any technology without client agreement"], correct: 1, explanation: "The ACA Code of Ethics requires counselors using technology to obtain informed consent, ensure client understanding of limitations and risks, maintain security/privacy, and possess competence with the technology used." },
  { domain: "Professional Orientation & Ethics", question: "Distance counseling via telehealth raises which ethical consideration that differs most from in-person counseling?", options: ["A) The need for informed consent", "B) The importance of confidentiality", "C) Emergency procedures and inability to immediately intervene in crisis situations", "D) The requirement for supervision of practice"], correct: 2, explanation: "While all ethical principles apply to distance counseling, emergency response capabilities differ significantly. Counselors must address emergency protocols, crisis response limitations, and how to access local emergency services." },
  { domain: "Professional Orientation & Ethics", question: "Regarding record keeping, ethical counselors maintain documentation that includes which information?", options: ["A) Only diagnoses and treatment plans", "B) Assessment data, treatment planning, progress notes, and clinical decision-making", "C) Copies of all personal information the counselor learns about the client", "D) Records only if the client requests them"], correct: 1, explanation: "Ethical record keeping includes assessment data, diagnoses, treatment plans, progress notes, and documentation of clinical decisions. Records should be accurate, timely, organized, and secure." },
  { domain: "Professional Orientation & Ethics", question: "A counselor's liability for malpractice most directly depends on which element?", options: ["A) Having a license or certification", "B) Practicing within the standard of care expected of a competent professional in similar circumstances", "C) Maintaining written case notes", "D) Being insured by a malpractice carrier"], correct: 1, explanation: "Malpractice liability stems from breaching the standard of care—failing to practice as a competent, reasonably prudent professional would in similar circumstances. Licenses and insurance don't prevent liability; competent practice does." },
  { domain: "Professional Orientation & Ethics", question: "Which of the following constitutes negligence in counseling practice?", options: ["A) A client disagreeing with a treatment recommendation", "B) Failing to provide adequate supervision or training, resulting in harm", "C) Counselors having personal challenges while working", "D) Clients not progressing as quickly as hoped"], correct: 1, explanation: "Negligence occurs when a counselor fails to provide the standard of care, directly resulting in client harm. This includes failures in supervision, training, diagnosis, or treatment planning." },
  { domain: "Professional Orientation & Ethics", question: "The principle of multicultural counseling competence requires counselors to address which aspect of practice?", options: ["A) Only learning about clients' cultural backgrounds", "B) Examining their own cultural assumptions, biases, and developing skills to work effectively across cultures", "C) Assuming all clients from a culture are identical", "D) Using only culture-specific interventions regardless of individual differences"], correct: 1, explanation: "Multicultural competence involves counselor self-awareness of cultural identity and biases, knowledge of cultural differences, and skills for culturally responsive practice. It's an ongoing developmental process." },
  { domain: "Professional Orientation & Ethics", question: "Which ethical consideration most directly addresses counselors' responsibility when working with clients from backgrounds different from their own?", options: ["A) Declining to work with clients from other cultures", "B) Recognizing and addressing their own cultural encapsulation and biases", "C) Assuming the client will teach the counselor about their culture", "D) Using generic treatment approaches without cultural adaptation"], correct: 1, explanation: "Counselors must actively recognize their own cultural assumptions, worldviews, and potential biases. Taking responsibility for cultural competence development protects clients and enables more effective practice." },
  { domain: "Professional Orientation & Ethics", question: "The concept of gatekeeping in the counseling profession refers to which responsibility?", options: ["A) Controlling access to counseling services", "B) Evaluating students' and counselors' fitness for the profession and intervening when fitness is compromised", "C) Setting fees for counseling services", "D) Determining which clients should receive which treatments"], correct: 1, explanation: "Gatekeeping involves counseling programs and supervisors evaluating whether students/counselors possess the competence, values, and wellness needed for ethical practice. It protects clients and maintains professional standards." },
  { domain: "Professional Orientation & Ethics", question: "A counseling graduate student demonstrates unethical behavior in a practicum course. According to professional standards, what should happen?", options: ["A) The student should continue without intervention", "B) The instructor should address the behavior and potentially implement remediation or recommend dismissal", "C) The behavior should be reported to the licensing board", "D) The student should be allowed to repeat the course indefinitely"], correct: 1, explanation: "Gatekeeping requires educators to address unethical student behavior through remediation plans or, if necessary, recommending dismissal from the program. This protects clients and maintains profession standards." },
  { domain: "Professional Orientation & Ethics", question: "Which of the following best represents the difference between the counselor's ethical duty of care and the counselor's legal duty?", options: ["A) Ethical duties are less strict than legal duties", "B) Ethical duties are often broader and require more than what law requires", "C) Legal duties and ethical duties are identical", "D) Counselors have no ethical duties if laws don't mandate them"], correct: 1, explanation: "Ethical standards often exceed legal minimums. Counselors must follow both law and professional ethics; when conflicts arise, counselors should seek to honor both by consulting supervisors and ethics committees." },
  { domain: "Professional Orientation & Ethics", question: "A counselor receives a subpoena for a client's records. Which action is most ethical while potentially protecting privilege?", options: ["A) Immediately release all records", "B) Refuse to acknowledge the client exists", "C) Consult with a lawyer and take steps to ensure privilege is properly raised in court", "D) Destroy the records before they can be subpoenaed"], correct: 2, explanation: "When subpoenaed, counselors should consult legal counsel and, where appropriate, assert privilege on behalf of the client. They can file motions and provide only what's legally required after privilege is waived." },
  { domain: "Professional Orientation & Ethics", question: "Regarding counselor competence, engaging in continuing education and professional development is most directly related to which ethical principle?", options: ["A) Beneficence", "B) Professional competence and integrity", "C) Autonomy", "D) Justice"], correct: 1, explanation: "Professional competence and integrity require counselors to maintain and improve skills through continuing education, supervision, and professional development. This ensures counselors provide current, effective services." },
  { domain: "Professional Orientation & Ethics", question: "A client discloses that they are experiencing suicidal ideation with specific plans. Which of the following is the counselor's primary ethical obligation?", options: ["A) Maintain confidentiality unless the client signs a release", "B) Assess lethality, implement safety measures, and warn identified individuals or contact emergency services", "C) Refer the client to a psychiatrist and discontinue counseling", "D) Document the disclosure but take no immediate action"], correct: 1, explanation: "Imminent danger to self overrides confidentiality. Counselors must assess risk, implement safety measures (including hospitalization if necessary), and take steps to protect the client from serious harm." },
  { domain: "Professional Orientation & Ethics", question: "Which of the following best describes the counselor's role regarding client self-determination and paternalism?", options: ["A) Counselors should make decisions for clients to protect them", "B) Counselors should provide information and support while respecting clients' right to make their own choices", "C) Counselors should only counsel clients who agree completely with the counselor's advice", "D) Self-determination applies only to adult clients, not minors"], correct: 1, explanation: "Respecting autonomy means providing information and support while allowing clients to make their own decisions. Paternalism (making decisions for clients) violates ethical principles unless imminent danger exists." },
  { domain: "Professional Orientation & Ethics", question: "The concept of informed refusal in counseling means which of the following?", options: ["A) Clients refusing to pay for services", "B) Clients declining a treatment recommendation after being informed of options and consequences", "C) Counselors refusing to see clients", "D) Refusing to complete documentation"], correct: 1, explanation: "Informed refusal means clients can decline recommended treatment after understanding the information about that treatment, alternatives, and risks of refusing. Counselors must respect this choice while addressing safety concerns." },
  { domain: "Professional Orientation & Ethics", question: "A counselor works with a client from a culture with very different norms regarding eye contact and personal space. How should the counselor ethically respond?", options: ["A) Insist the client make direct eye contact as a sign of trust", "B) Reduce personal space to establish rapport", "C) Understand cultural norms and adjust expectations while assessing the client's individual preferences", "D) Avoid discussing cultural differences to prevent offense"], correct: 2, explanation: "Culturally competent counselors learn cultural norms (etic knowledge) while recognizing individual variation (emic perspective). They adapt their approach based on cultural context and client preference." },
  { domain: "Professional Orientation & Ethics", question: "Regarding termination and transition in counseling, ethical standards require counselors to:", options: ["A) Terminate abruptly when the client no longer needs services", "B) Plan termination carefully, prepare the client, and facilitate transition to other services if needed", "C) Avoid discussing termination until the final session", "D) Encourage clients to continue indefinitely"], correct: 1, explanation: "Ethical termination involves collaborative planning, processing the relationship's ending, addressing the client's feelings, and facilitating transition if other services are needed." },
  { domain: "Professional Orientation & Ethics", question: "A counselor realizes a colleague is practicing under the influence of drugs or alcohol. According to the ACA Code of Ethics, the counselor should:", options: ["A) Say nothing to protect the colleague's reputation", "B) Immediately report to law enforcement", "C) Address the concern directly with the colleague and, if needed, report to appropriate authorities to protect clients", "D) Refuse to work with the colleague's clients"], correct: 2, explanation: "Counselors have an ethical duty to address impaired colleagues. This may involve direct conversation, peer assistance programs, or reporting to licensing boards to protect clients from harm." },
  { domain: "Professional Orientation & Ethics", question: "Which of the following is the most appropriate response to a counselor becoming aware of widespread unethical behavior in their agency?", options: ["A) Ignore it to maintain employment", "B) Discuss it only in private conversations", "C) Attempt to address it internally first, then report to appropriate licensing or ethics boards if unresolved", "D) Publicize it through social media"], correct: 2, explanation: "When aware of unethical practices, counselors should use internal processes first (supervisors, ethics committees), then escalate to licensing boards if needed. This protects clients while preserving professional relationships." },
  { domain: "Professional Orientation & Ethics", question: "Regarding counselor values and beliefs, the ACA Code of Ethics most directly requires counselors to:", options: ["A) Impose their values on clients", "B) Be aware of their own values and avoid imposing them on clients, especially when they conflict with clients' beliefs", "C) Never discuss values with clients", "D) Refer all clients whose values differ from their own"], correct: 1, explanation: "Counselors must examine their own values and worldviews, then practice in ways that respect clients' values and beliefs. This doesn't mean agreeing with clients but rather supporting their autonomy." },
  { domain: "Professional Orientation & Ethics", question: "A counselor is working with a client who has a religious belief that conflicts with a treatment approach the counselor recommends. What is the most ethical course of action?", options: ["A) Insist the client follow the counselor's recommendation", "B) Dismiss the client's religious belief as unhelpful", "C) Explore the belief, explain the rationale for the recommendation, and collaborate on an approach respectful of both", "D) Automatically refer the client elsewhere"], correct: 2, explanation: "Ethical practice involves respecting clients' spiritual and religious beliefs while exploring treatment options collaboratively. Counselors can advocate for an approach while ultimately respecting client choice." },
  { domain: "Professional Orientation & Ethics", question: "Which of the following best describes the counselor's responsibility regarding conflicts of interest in counseling relationships?", options: ["A) Conflicts of interest are unavoidable and therefore should not concern counselors", "B) Counselors should identify, disclose, and manage conflicts to prevent harm", "C) Conflicts of interest only matter if the client complains", "D) Counselors should always avoid any hint of conflict through isolation from clients"], correct: 1, explanation: "Counselors must proactively identify potential conflicts (financial, relational, professional) and disclose them to clients. Management strategies include consultation, referral, or clear boundaries." },
  { domain: "Professional Orientation & Ethics", question: "A long-term client asks the counselor for a personal loan. According to the ACA Code of Ethics, what should the counselor do?", options: ["A) Provide the loan to help a client in need", "B) Decline, explaining how lending could compromise the therapeutic relationship and represent a dual relationship", "C) Agree if the client demonstrates good credit", "D) Suggest the client take out a formal bank loan instead"], correct: 1, explanation: "Financial dealings with clients create dual relationships and conflicts of interest that compromise the therapeutic relationship. Counselors should decline and refer the client to appropriate financial resources." },
  { domain: "Professional Orientation & Ethics", question: "Regarding small-world practice issues (e.g., counseling in rural areas with limited providers), how should a counselor ethically navigate potential dual relationships?", options: ["A) Decline to practice in small communities to avoid all dual relationships", "B) Accept inevitable overlaps while carefully managing them to maintain boundaries and prevent harm", "C) Disclose nothing since everyone knows everyone anyway", "D) Treat dual relationships as acceptable without special consideration"], correct: 1, explanation: "In small communities, some role overlap is unavoidable. Ethical practice requires transparent discussion, careful boundary management, consultation, and documentation to minimize risk." },
  { domain: "Professional Orientation & Ethics", question: "A counselor is completing mandated reporter training. Which situation is the counselor most ethically obligated to report to child protective services?", options: ["A) A child mentioning their parent yelled at them", "B) Suspicion of child abuse or neglect based on observable indicators or disclosures", "C) Any time a parent uses physical discipline", "D) Situations the counselor thinks might eventually become abusive"], correct: 1, explanation: "Mandated reporters must report suspected abuse or neglect based on specific indicators or disclosures. General yelling doesn't rise to abuse; unfounded speculation isn't reported; but genuine suspicion is mandated." },
  { domain: "Professional Orientation & Ethics", question: "Regarding documentation in counseling, which of the following represents an ethical practice?", options: ["A) Keeping minimal notes to protect client privacy", "B) Documenting extensive personal opinions about clients", "C) Maintaining clear, objective, timely records that support treatment and demonstrate the standard of care", "D) Recording sessions without client consent for 'supervision purposes'"], correct: 2, explanation: "Ethical documentation is clear, objective, timely, and clinically relevant. It should include assessments, interventions, client progress, and clinical reasoning without unnecessary personal opinions." },
  { domain: "Professional Orientation & Ethics", question: "A counselor learns that a client is not the person they claimed to be (false identity). What ethical issues does this raise?", options: ["A) No ethical issues—the counselor should continue treatment unchanged", "B) Issues of informed consent, trust, and the genuineness of the therapeutic relationship", "C) Only issues if the client is dangerous", "D) Issues only if the client is paying with stolen credit cards"], correct: 1, explanation: "False identity compromises informed consent and trust. The counselor should address this, understand the reasons, consider implications for treatment safety, and determine whether to continue or refer." },
  { domain: "Professional Orientation & Ethics", question: "How should a counselor ethically handle a situation where they suspect a colleague is inappropriately touching or grooming a client?", options: ["A) Approach the colleague privately to warn them", "B) Do nothing unless the client complains", "C) Immediately report to supervisors, licensing boards, and law enforcement as appropriate", "D) Discuss it with other staff but not formally report"], correct: 2, explanation: "Suspected abuse or inappropriate conduct toward clients is a serious ethical and legal matter. Counselors must report to appropriate authorities (supervisors, licensing boards, law enforcement) to protect clients." },
  { domain: "Professional Orientation & Ethics", question: "Which of the following best describes the counselor's ethical obligation regarding competence with diverse client populations?", options: ["A) Counselors should work with only clients from their own cultural background", "B) Diversity competence is optional for counselors in predominantly homogeneous areas", "C) All counselors must develop multicultural competence as an ongoing professional responsibility", "D) Competence with diverse populations is less important than technical counseling skills"], correct: 2, explanation: "Multicultural competence is a fundamental ethical requirement for all counselors. It involves awareness, knowledge, and skills regarding cultural diversity and is an ongoing developmental process." },
  { domain: "Professional Orientation & Ethics", question: "A client shares that they are pursuing a medical procedure the counselor believes is harmful. What is the counselor's most ethical response?", options: ["A) Try to convince the client their decision is wrong", "B) Immediately terminate treatment", "C) Explore the client's values, concerns, and reasoning while respecting their autonomy", "D) Alert the client's family without permission"], correct: 2, explanation: "When clients make choices the counselor disagrees with, the ethical response is exploration and empathic understanding. Counselors advocate for client welfare while respecting their right to self-determination." },
  { domain: "Professional Orientation & Ethics", question: "Regarding the use of standardized assessments, which of the following represents an ethical practice?", options: ["A) Using any assessment available without considering cultural appropriateness", "B) Using only assessments developed by one publisher for consistency", "C) Selecting culturally appropriate, valid assessments and interpreting results with consideration of limitations", "D) Relying solely on client self-report without any formal assessment"], correct: 2, explanation: "Ethical assessment involves selecting appropriate, valid instruments; administering per guidelines; and interpreting results with awareness of cultural factors and assessment limitations." },
  { domain: "Professional Orientation & Ethics", question: "A counselor is aware that a client's insurance provider is denying coverage for continued treatment. What is the counselor's primary ethical responsibility?", options: ["A) Immediately discharge the client", "B) Accept the insurer's denial without advocacy", "C) Advocate for the client, explore alternative funding, and discuss options before terminating treatment", "D) Counsel the client to contest the decision but provide no assistance"], correct: 2, explanation: "When faced with coverage denials, counselors should advocate for clients, explore sliding scale or reduced fees, discuss pro bono options, and facilitate transition if termination is necessary." },
  { domain: "Professional Orientation & Ethics", question: "Which of the following best describes the principle of justice in counseling ethics?", options: ["A) Punishing clients who behave unethically", "B) Ensuring equitable access to counseling services and fair, non-discriminatory treatment", "C) Serving only the most educated or affluent clients", "D) Requiring all counseling to be free"], correct: 1, explanation: "Justice in counseling means treating all clients fairly and ensuring equitable access to services. It requires examining systemic barriers and working to reduce disparities in mental health care." },
  { domain: "Professional Orientation & Ethics", question: "A counselor is treating a client with a condition the counselor has never worked with before. What is the appropriate ethical approach?", options: ["A) Proceed as if fully competent", "B) Decline the client entirely", "C) Proceed with appropriate supervision, consultation, or continuing education to develop competence", "D) Refer immediately without attempting treatment"], correct: 2, explanation: "When encountering unfamiliar conditions, counselors can treat clients with appropriate support through supervision, consultation, and education. Full competence isn't required if seeking development is." },
  { domain: "Professional Orientation & Ethics", question: "Which of the following represents the most ethically sound approach to boundary setting with clients?", options: ["A) Rigid, inflexible boundaries regardless of context", "B) No boundaries to maximize therapeutic alliance", "C) Clear, transparent, consistent boundaries that protect the therapeutic relationship", "D) Boundaries that vary based on how much the counselor likes the client"], correct: 2, explanation: "Ethical boundaries are clear and transparent (discussed during informed consent), consistent, and maintained to protect clients and the therapeutic relationship. They're not punitive but protective." },
  { domain: "Professional Orientation & Ethics", question: "A client offers the counselor a substantial gift at the end of therapy. What is the counselor's most ethical response?", options: ["A) Accept graciously to avoid offending the client", "B) Accept and document in the client record", "C) Decline thoughtfully, explore the meaning, and discuss policy", "D) Accept but provide the gift to charity"], correct: 2, explanation: "Counselors should decline gifts, particularly substantial ones, to maintain boundaries. Exploring the client's motivation and explaining policy is part of ethical closure." },
  { domain: "Professional Orientation & Ethics", question: "Regarding the ACA Code of Ethics principle of beneficence, which best describes what it requires?", options: ["A) Doing whatever the client requests", "B) Working to promote client welfare and positive growth", "C) Ensuring the counselor profits from the therapeutic relationship", "D) Making decisions for clients based on counselor judgment"], correct: 1, explanation: "Beneficence requires counselors to work toward client benefit and positive outcomes. This involves promoting growth, healing, and improved functioning while respecting autonomy." },
  { domain: "Professional Orientation & Ethics", question: "Which of the following best describes the difference between a counselor's use of power in helping versus harm?", options: ["A) Power is inherently harmful and should never be used", "B) Power differences are irrelevant in counseling relationships", "C) Counselors should use their influence to promote client autonomy and benefit, not control", "D) Counselors have no power in relationships with clients"], correct: 2, explanation: "The therapeutic relationship inherently involves power differences. Ethically, counselors use this influence to facilitate client growth and autonomy, never for personal benefit or control." },
  { domain: "Professional Orientation & Ethics", question: "A counselor receives ongoing consultation and supervision for their work. How does this most directly support ethical practice?", options: ["A) It reduces the counselor's professional responsibility", "B) It allows identification of blind spots, ensures current competence, and addresses ethical concerns", "C) It's required only for new counselors, not experienced ones", "D) It primarily protects the agency from liability"], correct: 1, explanation: "Regular supervision and consultation support ethical practice by providing external perspective, identifying blind spots, addressing ethical dilemmas, and ensuring the counselor's continued competence." },
  { domain: "Professional Orientation & Ethics", question: "Regarding fees and compensation, which of the following represents an ethical issue for counselors?", options: ["A) Charging for services rendered", "B) Establishing sliding scales based on income", "C) Charging different rates to different clients without transparent criteria", "D) Having a clear written fee policy"], correct: 2, explanation: "Fee practices should be transparent and non-discriminatory. Counselors must disclose fees upfront and have consistent, clear policies. Arbitrary differential pricing without clear criteria is problematic." },
  { domain: "Professional Orientation & Ethics", question: "A counselor is asked by a supervisor to counsel a client in an area where the counselor lacks competence. What is the counselor's most appropriate response?", options: ["A) Comply to please the supervisor", "B) Refuse to see any clients in that area", "C) Respectfully decline and propose a referral while offering to develop competence", "D) Accept but work only on familiar aspects of the case"], correct: 2, explanation: "Counselors must respectfully decline assignments exceeding their competence, even if supervisors request it. They should propose referrals and may work to develop competence with support." },
  { domain: "Professional Orientation & Ethics", question: "Regarding emergency procedures in counseling, what is the counselor's responsibility?", options: ["A) Hope emergencies don't occur", "B) Have protocols for managing crises, safety concerns, and access to emergency services", "C) Only manage emergencies that occur during counseling sessions", "D) Rely entirely on emergency responders without direct involvement"], correct: 1, explanation: "Ethically competent counselors develop and implement emergency protocols for crises, safety concerns, and access to psychiatric care. These should be in place before emergencies occur." },
  { domain: "Professional Orientation & Ethics", question: "A client tells the counselor they're planning to harm someone specific. The counselor has never heard of Tarasoff. Ethically, what should the counselor do?", options: ["A) Keep the confidence because of the duty not to harm the relationship", "B) Wait to see if the client acts before intervening", "C) Immediately take reasonable steps to warn the victim and notify authorities", "D) Only tell the client they should seek other help"], correct: 2, explanation: "Even without knowing Tarasoff by name, counselors have an ethical duty to protect identifiable victims from serious harm. This overrides confidentiality and requires warning and reporting." },
  { domain: "Professional Orientation & Ethics", question: "When a counselor lacks cultural knowledge about a client's background, what is the most ethical approach?", options: ["A) Pretend to have knowledge to appear competent", "B) Ask the client to educate the counselor, placing sole responsibility on the client", "C) Seek education through reading, consultation, and community learning while collaboratively exploring the client's culture", "D) Refer all clients from unfamiliar cultures elsewhere"], correct: 2, explanation: "Counselors should pursue cultural education proactively while also respectfully inviting client perspective. This collaborative, humble approach benefits the therapeutic relationship while building competence." },
  { domain: "Professional Orientation & Ethics", question: "Regarding online counseling platforms and apps, which of the following raises an ethical concern?", options: ["A) Any use of technology in counseling", "B) Using platforms without establishing security, informed consent, and understanding limitations", "C) Counselors learning new technologies", "D) Clients having access to their own records electronically"], correct: 1, explanation: "Online platforms require counselors to address informed consent (including tech limitations), security/privacy (HIPAA compliance), emergency protocols, and counselor competence with the technology." },
  { domain: "Professional Orientation & Ethics", question: "A counselor works with a teenage client whose parents demand to know everything discussed in sessions. How should the counselor ethically respond?", options: ["A) Disclose everything to parents", "B) Maintain complete confidentiality from parents", "C) Explain the limits of confidentiality regarding the minor, involve the minor in determining what's shared, and balance safety with the minor's emerging autonomy", "D) Refuse to work with minors"], correct: 2, explanation: "With minors, counselors balance parental rights with the minor's developing autonomy and privacy. They typically share information about safety concerns while protecting appropriate privacy." },
  { domain: "Professional Orientation & Ethics", question: "Which of the following is an example of a professional boundary violation?", options: ["A) Discussing fees and cancellation policy at the start of counseling", "B) Offering clients your personal cell phone number for emergencies between sessions", "C) Explaining your theoretical approach to the client", "D) Discussing the limits of confidentiality during informed consent"], correct: 1, explanation: "Providing personal cell numbers or other means of direct contact outside professional channels can compromise boundaries and create accessibility that interferes with treatment structure." },
  { domain: "Professional Orientation & Ethics", question: "According to current ethical standards, the most critical factor in becoming a culturally competent counselor is:", options: ["A) Reading books about diverse cultures", "B) Having clients from diverse backgrounds", "C) Ongoing self-examination of one's own cultural identity, biases, and assumptions", "D) Memorizing cultural facts about various groups"], correct: 2, explanation: "Multicultural competence begins with self-awareness. Counselors must examine their own cultural identity, worldviews, and biases before they can effectively work across differences." },
  { domain: "Professional Orientation & Ethics", question: "A counselor realizes they have made an error in treatment that may have harmed the client. What is the most ethical course of action?", options: ["A) Hope the client doesn't discover the error", "B) Disclose the error, apologize, and work to remediate harm while consulting supervisors or ethics boards", "C) Blame external factors or the client for the problem", "D) Immediately terminate the relationship to avoid further contact"], correct: 1, explanation: "When errors occur, ethical counselors acknowledge them, apologize, explain remediation, and seek guidance. Transparency and accountability help preserve trust and may prevent further harm." },
  { domain: "Professional Orientation & Ethics", question: "Regarding the use of social media by counselors, which of the following represents an ethical concern?", options: ["A) Counselors having any online presence at all", "B) Blurred boundaries between professional and personal life, potential confidentiality breaches, and inappropriate client-counselor contact", "C) Providing professional information through a website", "D) Clients being able to find professional qualifications online"], correct: 1, explanation: "Social media risks include boundary blur, potential confidentiality issues, inappropriate client-counselor contact, and conflicts of interest. Counselors should maintain professional boundaries even online." }
];

const DIVERSITY_QUESTIONS = [
  { domain: "Social & Cultural Diversity", question: "Sue and Sue's multicultural counseling competencies model addresses which three core dimensions of cultural competence?", options: ["A) Knowledge, awareness, and skills", "B) Attitudes, beliefs, and behaviors", "C) Diagnosis, treatment, and outcome", "D) Assessment, conceptualization, and intervention"], correct: 0, explanation: "Sue and Sue's foundational framework identifies three dimensions: (1) awareness of counselor's own cultural assumptions and biases, (2) knowledge of diverse worldviews and cultural information, and (3) skills for culturally responsive interventions." },
  { domain: "Social & Cultural Diversity", question: "According to Cross's model of cultural identity development, individuals progress through which stages?", options: ["A) Pre-encounter, encounter, immersion-emersion, internalization, and internalization-commitment", "B) Awareness, knowledge, skill, and mastery", "C) Beginning, intermediate, advanced, and expert", "D) Exposure, learning, application, and mastery"], correct: 0, explanation: "Cross's Nigrescence model describes Black racial identity development through five stages: pre-encounter (low cultural awareness), encounter (experiences prompting awareness), immersion-emersion (high cultural immersion), internalization, and internalization-commitment (integrating identity into broader self)." },
  { domain: "Social & Cultural Diversity", question: "Helms' White racial identity development model includes which stage where individuals first recognize White privilege and systemic racism?", options: ["A) Contact", "B) Disintegration", "C) Reintegration", "D) Autonomy"], correct: 1, explanation: "Disintegration is the stage where White individuals acknowledge racial inequities and White privilege for the first time, often causing confusion and guilt. This recognition is a crucial step in developing racial awareness." },
  { domain: "Social & Cultural Diversity", question: "The Atkinson, Sue, and Morten Racial/Cultural Identity Development (R/CID) model applies to which populations?", options: ["A) Only White Americans", "B) Only African Americans", "C) Racial and ethnic minority groups across diverse backgrounds", "D) Only Asian Americans"], correct: 2, explanation: "The R/CID model was developed to describe identity development across multiple racial and ethnic minority groups. It proposes four stages: conformity, dissonance, resistance and immersion, and introspection and synergetic articulation." },
  { domain: "Social & Cultural Diversity", question: "According to the R/CID model, the 'conformity' stage is characterized by which beliefs?", options: ["A) Complete rejection of the dominant culture", "B) Preference for the dominant culture and devaluation of one's own culture", "C) Integration of multiple cultural perspectives", "D) Exclusive focus on one's ethnic heritage"], correct: 1, explanation: "In the conformity stage, individuals often prefer the dominant culture's values and aesthetics while devaluing their own culture. This stage may involve internal conflict and self-devaluation." },
  { domain: "Social & Cultural Diversity", question: "Poston's biracial identity development model differs from uniracial models in that it specifically addresses which experience?", options: ["A) The linear progression of identity formation", "B) The unique challenges of integrating multiple racial identities", "C) The similarities between biracial and monoracial identity", "D) The superiority of biracial identity"], correct: 1, explanation: "Poston's model acknowledges that biracial individuals navigate unique developmental tasks—integrating multiple racial identities—rather than following uniracial models. His model includes stages specific to biracial experience." },
  { domain: "Social & Cultural Diversity", question: "Cass's homosexual identity development model proposes how many stages?", options: ["A) Three stages", "B) Four stages", "C) Six stages", "D) Eight stages"], correct: 2, explanation: "Cass proposed six stages of sexual identity development: identity confusion, identity comparison, identity tolerance, identity acceptance, identity pride, and identity synthesis. This model applies primarily to gay and lesbian individuals." },
  { domain: "Social & Cultural Diversity", question: "In Cass's model, the 'identity synthesis' stage involves which developmental achievement?", options: ["A) Complete acceptance of heterosexuality", "B) Integration of sexual identity as one aspect of the total self", "C) Public announcement of sexual orientation", "D) Rejection of societal norms"], correct: 1, explanation: "Identity synthesis is the final stage where individuals view sexual identity as one important aspect of their overall identity. Sexual orientation is integrated rather than compartmentalized." },
  { domain: "Social & Cultural Diversity", question: "D'Andrea and Daniels developed the RESPECTFUL model to enhance counselor competence with which populations?", options: ["A) Only racial minority clients", "B) Only clients with disabilities", "C) All clients from diverse backgrounds across multiple dimensions", "D) Only immigrant populations"], correct: 2, explanation: "The RESPECTFUL model addresses multiple dimensions of diversity: Religion/Spirituality, Economic status, Sexual orientation, Psychological maturity, Ethnicity/Race, Chronological age, Trauma, Family history, Unique ability, and Location." },
  { domain: "Social & Cultural Diversity", question: "The distinction between emic and etic perspectives in cultural understanding refers to which aspect?", options: ["A) Economic versus academic viewpoints", "B) Insider (cultural member) versus outsider (external observer) perspectives", "C) Emotional versus rational perspectives", "D) Early versus contemporary cultural traditions"], correct: 1, explanation: "Emic perspective is the insider's view—how cultural members understand their own culture. Etic perspective is the outsider's observational view. Counselors need both for cultural understanding." },
  { domain: "Social & Cultural Diversity", question: "Berry's model of acculturation includes which orientations?", options: ["A) Acceptance and rejection only", "B) Integration, assimilation, separation, and marginalization", "C) Tradition and modernity", "D) Individual and collectivist"], correct: 1, explanation: "Berry's framework describes how individuals relate to their heritage culture and the dominant culture: integration (maintaining both), assimilation (adopting dominant only), separation (maintaining heritage only), and marginalization (identifying with neither)." },
  { domain: "Social & Cultural Diversity", question: "In Berry's acculturation model, 'biculturalism' most closely aligns with which orientation?", options: ["A) Assimilation", "B) Separation", "C) Integration", "D) Marginalization"], correct: 2, explanation: "Integration/biculturalism involves maintaining one's heritage culture while also adapting to and participating in the dominant culture. This outcome typically shows the best mental health outcomes." },
  { domain: "Social & Cultural Diversity", question: "Cultural encapsulation, as described by Wrenn, refers to counselors being trapped within which limitations?", options: ["A) Physical therapy models", "B) Their own cultural frameworks, unable to see outside their worldview", "C) Diagnostic categories", "D) Insurance reimbursement limitations"], correct: 1, explanation: "Cultural encapsulation describes counselors bounded by their own cultural perspectives, unable to recognize or value different worldviews. This limits their effectiveness with culturally diverse clients." },
  { domain: "Social & Cultural Diversity", question: "The concept of 'worldview' in multicultural counseling addresses which aspect of cultural understanding?", options: ["A) Only how people view geography", "B) Individual views of religion only", "C) The broader frameworks through which people perceive reality, including individualism-collectivism", "D) Political ideologies exclusively"], correct: 2, explanation: "Worldview encompasses how cultures perceive reality, relating to individualism vs. collectivism, time orientation, control over environment, and human relationships. Understanding clients' worldviews is essential for counseling." },
  { domain: "Social & Cultural Diversity", question: "Individualism versus collectivism as cultural dimensions most directly relates to which counseling consideration?", options: ["A) Insurance coverage decisions", "B) How clients view the self in relation to family and community", "C) Vocabulary used in counseling", "D) Geographic location of the client"], correct: 1, explanation: "Individualistic cultures emphasize personal goals and autonomy; collectivistic cultures prioritize family and community harmony. These orientations profoundly affect counseling goals and communication styles." },
  { domain: "Social & Cultural Diversity", question: "Power, privilege, and oppression in counseling most directly relate to which systemic issue?", options: ["A) Individual psychopathology", "B) Unequal access to resources and opportunities based on group membership", "C) Personal motivation and effort", "D) Educational background alone"], correct: 1, explanation: "These concepts address systemic inequalities where dominant groups have advantages while marginalized groups face barriers. Counselors must understand these structures to practice equitably." },
  { domain: "Social & Cultural Diversity", question: "Sue's concept of microaggressions refers to which type of behavior?", options: ["A) Major acts of violence toward group members", "B) Intentional slurs and obvious discrimination", "C) Brief, everyday slights and invalidations based on group membership", "D) Only overt discrimination"], correct: 2, explanation: "Microaggressions are subtle, often unintentional slights—comments, gestures, or behaviors that demean or invalidate individuals based on their group identity. Cumulative impact can cause significant psychological harm." },
  { domain: "Social & Cultural Diversity", question: "When counseling someone experiencing microaggressions, which is the counselor's appropriate focus?", options: ["A) Minimizing the impact as 'unintentional'", "B) Defending the perpetrator's intent", "C) Validating the client's experience and exploring the cumulative impact", "D) Assuming the client is oversensitive"], correct: 2, explanation: "Counselors should validate that microaggressions, regardless of intent, are real and harmful. The cumulative impact of these slights contributes to stress and mental health concerns." },
  { domain: "Social & Cultural Diversity", question: "Social class and socioeconomic status (SES) in counseling affect which outcomes?", options: ["A) Only determining whether someone deserves treatment", "B) Access to mental health services, therapeutic relationships, and counseling outcomes", "C) Nothing; counseling is equally accessible to everyone", "D) Only the type of diagnosis"], correct: 1, explanation: "SES significantly affects access to care, ability to afford counseling, time availability, and even therapeutic matching. Counselors must recognize SES-based barriers and advocate for equitable access." },
  { domain: "Social & Cultural Diversity", question: "The concept of 'social class' extends beyond income to include which factors?", options: ["A) Only money earned", "B) Education, occupation, income, power, and family background", "C) Genetic factors", "D) Only occupation"], correct: 1, explanation: "Social class encompasses multiple dimensions: income, education level, occupational status, family background, social networks, and cultural capital. These intersect to shape life experiences and opportunities." },
  { domain: "Social & Cultural Diversity", question: "In counseling, gender identity differs from biological sex in that it refers to which aspect?", options: ["A) Reproductive capacity", "B) Chromosomal makeup", "C) One's internal sense of gender, which may differ from sex assigned at birth", "D) Only legal identification"], correct: 2, explanation: "Gender identity is the internal, personal sense of one's gender. It may align with or differ from sex assigned at birth. Counselors must respect clients' gender identity regardless of biological factors." },
  { domain: "Social & Cultural Diversity", question: "Sexual orientation describes which aspect of human experience?", options: ["A) The gender someone is physically attracted to", "B) Sexual behaviors only", "C) Emotional, romantic, and/or sexual attraction to others", "D) Only sexual activity"], correct: 2, explanation: "Sexual orientation encompasses the pattern of emotional, romantic, and sexual attraction someone experiences toward others. It's distinct from sexual behavior and includes identities like heterosexual, gay, lesbian, and bisexual." },
  { domain: "Social & Cultural Diversity", question: "Regarding LGBTQ+ issues in counseling, which is a significant mental health concern related to minority stress?", options: ["A) Sexual orientation and gender identity themselves cause mental illness", "B) Discrimination, internalized stigma, victimization, and lack of social support contribute to higher rates of certain mental health concerns", "C) LGBTQ+ individuals are inherently less mentally healthy", "D) Mental health counseling should attempt to change sexual orientation or gender identity"], correct: 1, explanation: "Minority stress model demonstrates that elevated rates of anxiety, depression, and substance use among LGBTQ+ populations stem from discrimination and stigma, not from identity itself. Affirming counseling supports mental health." },
  { domain: "Social & Cultural Diversity", question: "Conversion therapy or 'reparative therapy' is considered unethical because it:", options: ["A) Doesn't involve enough sessions", "B) Is ineffective at changing orientation/identity, causes harm, and violates the person's right to self-determination", "C) Is not approved by insurance companies", "D) Isn't based on psychodynamic theory"], correct: 1, explanation: "Major professional organizations (APA, ACA, AMA) oppose conversion therapy as harmful and ineffective. It violates autonomy, causes psychological damage, and is based on the false premise that LGBTQ+ identity is pathological." },
  { domain: "Social & Cultural Diversity", question: "Disability culture and the social model of disability address which understanding?", options: ["A) Disabilities are primarily individual medical problems", "B) Disabilities result only from physical or cognitive differences", "C) Disability is partly created by societal barriers and lack of accommodations, not just individual limitations", "D) People with disabilities should hide their disabilities"], correct: 2, explanation: "The social model views disability as partly created by societal barriers, accessibility gaps, and discrimination. This contrasts with the medical model that locates disability entirely within the individual." },
  { domain: "Social & Cultural Diversity", question: "Ableism in counseling refers to which type of bias?", options: ["A) Discrimination against people based on physical ability", "B) Assumptions that disability is inherently negative or less valuable", "C) Both discrimination and assumptions that privilege able-bodied people", "D) Only jokes about disabilities"], correct: 2, explanation: "Ableism is discrimination and prejudice against people with disabilities, including assumptions that able-bodied status is superior. Counselors must examine their own ableist biases and provide accessible services." },
  { domain: "Social & Cultural Diversity", question: "When counseling someone with a disability, which approach is most appropriate?", options: ["A) Assuming disability is the primary issue in all counseling concerns", "B) Completely ignoring the disability", "C) Understanding the disability and its impact while also viewing the person as a complete individual with strengths", "D) Recommending they focus exclusively on disability-related issues"], correct: 2, explanation: "Effective counseling with disabled clients involves acknowledging disability when relevant while recognizing the whole person. Not every concern stems from disability; counselors should ask rather than assume." },
  { domain: "Social & Cultural Diversity", question: "Immigration and acculturation stress can contribute to which mental health concerns?", options: ["A) Nothing—immigrants always adjust well", "B) Only grief and homesickness", "C) Anxiety, depression, and identity challenges related to cultural adjustment and loss", "D) Only economic stress"], correct: 2, explanation: "Immigrants often experience significant stress: language barriers, discrimination, loss of cultural context, family separation, economic challenges, and identity questions. These contribute to anxiety, depression, and adjustment difficulties." },
  { domain: "Social & Cultural Diversity", question: "When counseling immigrant or refugee clients, which factor most directly affects counseling relationship?", options: ["A) The language spoken before immigration", "B) Trust in authority figures, which may be affected by past trauma or persecution", "C) The client's favorite foods", "D) The immigration date"], correct: 1, explanation: "Immigrants and refugees may have trauma histories involving government persecution, violence, or displacement. These experiences affect trust in authority—including counselors—requiring cultural humility and transparency." },
  { domain: "Social & Cultural Diversity", question: "Refugee trauma differs from typical trauma counseling needs in which way?", options: ["A) It's less serious than other trauma", "B) It typically involves persecution, violence, and displacement before resettlement", "C) It doesn't require specialized counseling", "D) Only military personnel experience refugee trauma"], correct: 1, explanation: "Refugee trauma often includes war, persecution, violence, loss of family and homeland, and precarious resettlement conditions. Counselors need specialized knowledge about complex trauma and acculturation stress." },
  { domain: "Social & Cultural Diversity", question: "When counseling Indigenous or Native American clients, which historical context is essential to understand?", options: ["A) Only contemporary tribal politics", "B) Only modern tribal governance", "C) Intergenerational trauma from colonization, forced assimilation, and ongoing systemic inequities", "D) Only language differences"], correct: 2, explanation: "Understanding Native American/Indigenous mental health requires knowledge of historical trauma (colonization, forced removal, boarding schools), ongoing discrimination, and current health disparities. This context shapes clients' experiences." },
  { domain: "Social & Cultural Diversity", question: "The concept of 'historical trauma' in Indigenous communities refers to which phenomenon?", options: ["A) Trauma from historical events that ended long ago", "B) Intergenerational psychological wounds from collective experiences of colonization and oppression", "C) Only traumatic events specific to one person", "D) Something that doesn't affect current generations"], correct: 1, explanation: "Historical trauma describes how collective experiences of genocide, displacement, and assimilation policies create intergenerational psychological effects in Indigenous communities, affecting mental health across generations." },
  { domain: "Social & Cultural Diversity", question: "Racial and ethnic identity development includes understanding which relationship?", options: ["A) Only financial status", "B) How individuals incorporate their racial/ethnic heritage into their sense of self", "C) Only occupational choices", "D) Language spoken exclusively"], correct: 1, explanation: "Racial/ethnic identity development involves how people understand and incorporate their race and ethnicity into their identity, relate to others with shared identity, and navigate majority/minority status." },
  { domain: "Social & Cultural Diversity", question: "The concept of 'locus of control' (Rotter) refers to which belief?", options: ["A) Where people geographically live", "B) Whether individuals believe they control outcomes (internal) or outcomes are controlled by external forces", "C) How people control their emotions", "D) Only political beliefs"], correct: 1, explanation: "Locus of control describes whether individuals attribute outcomes to internal factors (personal effort) or external factors (chance, powerful others). Cultural differences exist; some cultures emphasize external locus." },
  { domain: "Social & Cultural Diversity", question: "The concept of 'locus of responsibility' differs from locus of control in that it addresses which consideration?", options: ["A) Only money management", "B) Whether individuals blame themselves or their circumstances for problems", "C) Only academic performance", "D) Only family relationships"], correct: 1, explanation: "Locus of responsibility addresses attribution—whether individuals blame themselves personally for problems or recognize external circumstances and systemic factors. This affects self-blame and shame." },
  { domain: "Social & Cultural Diversity", question: "Proxemics—the study of how people use space—reveals which cultural difference?", options: ["A) How people feel about furniture", "B) Variations in comfortable interpersonal distance and spatial arrangements across cultures", "C) How climates differ geographically", "D) Personal preferences for room colors"], correct: 1, explanation: "Proxemics shows that comfortable interpersonal distance varies culturally. Some cultures prefer closer proximity; others maintain greater distance. Mismatches can create discomfort." },
  { domain: "Social & Cultural Diversity", question: "Kinesics in cross-cultural counseling refers to which communication aspect?", options: ["A) Movement and body language", "B) The distance between people", "C) Tone of voice", "D) Vocabulary choices"], correct: 0, explanation: "Kinesics studies body language, gestures, facial expressions, and movement. These vary culturally—same gestures mean different things across cultures. Counselors must interpret kinesics within cultural context." },
  { domain: "Social & Cultural Diversity", question: "Paralinguistics in communication includes which elements?", options: ["A) Only the words spoken", "B) Voice tone, volume, pace, pitch, and other vocal qualities beyond words", "C) Only body language", "D) Only written communication"], correct: 1, explanation: "Paralinguistics encompasses vocal qualities—tone, volume, rate, pitch, emphasis—that communicate meaning beyond words. Cultural differences exist in acceptable volume and pace." },
  { domain: "Social & Cultural Diversity", question: "High-context versus low-context cultures differ most fundamentally in which communication aspect?", options: ["A) Language families", "B) Whether meaning derives from explicit words (low-context) or from context, relationship, and nonverbals (high-context)", "C) Vocabulary size", "D) Literacy rates"], correct: 1, explanation: "High-context cultures (many Asian, African, Latin American) rely on relationship, nonverbals, and context; low-context cultures (Northern European, North American) emphasize explicit verbal communication. This affects counselor-client communication." },
  { domain: "Social & Cultural Diversity", question: "When counseling a client from a high-context culture, what communication adaptation might be appropriate?", options: ["A) Use only direct, explicit statements", "B) Ignore context and focus only on words", "C) Attend to nonverbal communication, relationship building, and implied meanings", "D) Assume low-context expectations"], correct: 2, explanation: "High-context clients may communicate indirectly and value relationship before discussing issues. Counselors should slow down, build rapport, attend to nonverbals, and avoid pushing for premature disclosure." },
  { domain: "Social & Cultural Diversity", question: "Spirituality and religion in counseling raise which ethical consideration?", options: ["A) Counselors should impose their own spiritual beliefs", "B) Spirituality is irrelevant to mental health", "C) Counselors should explore clients' spiritual beliefs and values while respecting autonomy", "D) Religious beliefs always indicate pathology"], correct: 2, explanation: "Spirituality and religion significantly affect worldview, coping, meaning-making, and mental health. Counselors should explore these with respect while avoiding imposition of their own beliefs." },
  { domain: "Social & Cultural Diversity", question: "When a counselor's spiritual beliefs conflict with a client's worldview, what is the ethical approach?", options: ["A) Convert the client to the counselor's beliefs", "B) Dismiss the client's beliefs", "C) Explore both perspectives, respect the client's autonomy, and refer if the conflict impairs treatment", "D) Pretend the beliefs don't exist"], correct: 2, explanation: "Counselors should acknowledge belief differences, explore respectfully, and maintain clients' rights to their own beliefs. If conflicts significantly impair the relationship, referral is appropriate." },
  { domain: "Social & Cultural Diversity", question: "Aging and gerontological counseling addresses which population's specific needs?", options: ["A) Only people over 65", "B) Older adults facing life transitions, health changes, loss, and adjusted life roles", "C) Only cognitive decline", "D) Only people in nursing homes"], correct: 1, explanation: "Gerontological counseling addresses older adults' unique challenges: retirement adjustment, health changes, loss of loved ones, reduced social roles, and existential concerns about mortality and legacy." },
  { domain: "Social & Cultural Diversity", question: "Ageism in counseling refers to which type of bias?", options: ["A) Studying how age affects development", "B) Stereotyping and discriminating against people based on age, assuming decline or reduced capability", "C) Celebrating birthdays", "D) Age-appropriate education"], correct: 1, explanation: "Ageism involves stereotypes that older adults are less capable, less attractive, or less worthy. It affects treatment quality, counselor assumptions, and medication recommendations. Counselors must examine ageist biases." },
  { domain: "Social & Cultural Diversity", question: "The D'Andrea and Daniels RESPECTFUL model includes 'Trauma' as a dimension addressing which consideration?", options: ["A) Only major catastrophic events", "B) Current and historical traumatic experiences affecting clients' mental health", "C) Only war-related trauma", "D) Only childhood abuse"], correct: 1, explanation: "The RESPECTFUL model recognizes trauma as a diversity dimension—current and historical trauma affects clients' psychological functioning, worldview, trust, and counseling needs." },
  { domain: "Social & Cultural Diversity", question: "Strong's social influence model in counseling proposes that counselor effectiveness depends partly on which factors?", options: ["A) Only counselor credentials", "B) The counselor's perceived expertise, trustworthiness, and attractiveness to the client", "C) Only the counselor's theoretical orientation", "D) Exclusively on client factors"], correct: 1, explanation: "Strong's model indicates that clients are influenced by counselors perceived as expert (knowledgeable), trustworthy (reliable, honest), and attractive (personable, valued). These factors enhance therapeutic influence." },
  { domain: "Social & Cultural Diversity", question: "Cognitive dissonance (Festinger) occurs when individuals hold beliefs that:", options: ["A) Are too complex to understand", "B) Contradict each other, creating psychological discomfort motivating change", "C) Are entirely consistent", "D) Are unimportant"], correct: 1, explanation: "Cognitive dissonance describes the discomfort from holding contradictory beliefs or values. This motivates individuals to reduce discomfort by changing beliefs, behaviors, or justifications." },
  { domain: "Social & Cultural Diversity", question: "In counseling, understanding cognitive dissonance helps explain why clients might:", options: ["A) Change nothing despite recognizing a problem", "B) Experience discomfort when their behavior contradicts their values, potentially motivating change", "C) Immediately make perfect decisions", "D) Always act rationally"], correct: 1, explanation: "When clients recognize that their behaviors contradict their values, cognitive dissonance creates discomfort that can motivate change. Counselors can highlight these inconsistencies to facilitate growth." },
  { domain: "Social & Cultural Diversity", question: "Ethnocentrism in counseling refers to which problematic perspective?", options: ["A) Learning about other cultures", "B) Viewing one's own culture as superior and the standard against which to judge others", "C) Celebrating diverse cultures", "D) Only studying ethics"], correct: 1, explanation: "Ethnocentrism is viewing one's own culture as the norm and superior standard, judging other cultures by those standards. This limits cultural understanding and effective cross-cultural counseling." },
  { domain: "Social & Cultural Diversity", question: "Stereotyping in counseling most directly harms clients by:", options: ["A) Teaching them about their culture", "B) Ignoring individual differences and assigning characteristics based solely on group membership", "C) Being factually accurate", "D) Only describing group patterns"], correct: 1, explanation: "Stereotyping overlooks individual variation and attributes group characteristics to individuals, reducing them to group members. This limits seeing clients' unique strengths, challenges, and needs." },
  { domain: "Social & Cultural Diversity", question: "Prejudice differs from discrimination in that prejudice is:", options: ["A) Only negative attitudes", "B) A negative attitude or belief, while discrimination is the harmful action based on that attitude", "C) The same as discrimination", "D) Only related to race"], correct: 1, explanation: "Prejudice is an attitude or belief (often negative); discrimination is the behavioral expression—treating people unfairly based on group membership. Both exist and are problematic." },
  { domain: "Social & Cultural Diversity", question: "YAVIS bias (Youthful, Attractive, Verbal, Intelligent, Successful) in therapy suggests which counselor tendency?", options: ["A) Counselors only work with YAVIS clients", "B) Counselors may preferentially work with and have better outcomes with clients matching YAVIS characteristics", "C) YAVIS clients need therapy less", "D) YAVIS characteristics guarantee good counseling outcomes"], correct: 1, explanation: "Research shows counselors may have more favorable views and better therapeutic relationships with YAVIS clients. Counselors must actively work to provide equitable, quality care for all clients." },
  { domain: "Social & Cultural Diversity", question: "QUOID bias (lower socioeconomic status, older, less intelligent, introversion, disabled) reflects counselor tendencies to:", options: ["A) Provide better care to these clients", "B) View these clients less favorably, potentially providing lower-quality services", "C) Prioritize these clients", "D) These clients don't need therapy"], correct: 1, explanation: "QUOID bias describes counselor tendencies to view these clients less favorably and potentially offer less-sophisticated interventions. Counselors must actively counter this bias." },
  { domain: "Social & Cultural Diversity", question: "Intersectionality in counseling refers to which concept?", options: ["A) People having only one identity", "B) The overlapping, interconnected nature of multiple social identities affecting someone's lived experience", "C) Geographic locations", "D) Only addressing the largest social group someone belongs to"], correct: 1, explanation: "Intersectionality recognizes that individuals hold multiple social identities (race, gender, class, sexuality, ability, etc.) that interact and create unique experiences. A Black woman's experience differs from Black men's or White women's." },
  { domain: "Social & Cultural Diversity", question: "Understanding intersectionality helps counselors recognize that a client's experience is shaped by:", options: ["A) Only their race", "B) Only their gender", "C) Only their class", "D) The unique interaction of their multiple identities"], correct: 3, explanation: "Intersectionality emphasizes that people's experiences result from how their multiple identities interact, not from any single identity alone. This affects mental health concerns, strengths, and needed interventions." },
  { domain: "Social & Cultural Diversity", question: "Cultural relativism in counseling means:", options: ["A) All counseling practices are equally good regardless of culture", "B) Understanding and respecting cultural practices within their own context without imposing external judgment", "C) Counselors should never challenge any cultural belief", "D) All cultures are identical"], correct: 1, explanation: "Cultural relativism involves understanding practices within cultural context rather than applying external standards. It differs from moral relativism—counselors still address harmful practices while respecting cultural values." },
  { domain: "Social & Cultural Diversity", question: "The concept of 'cultural humility' differs from 'cultural competence' in that it emphasizes:", options: ["A) Superior knowledge of all cultures", "B) Ongoing self-reflection, recognizing limits of knowledge, and valuing clients' expertise about their culture", "C) Mastery of cultural facts", "D) Never making mistakes about culture"], correct: 1, explanation: "Cultural humility stresses lifelong learning, acknowledging what counselors don't know, examining power dynamics, and valuing clients as experts on their own culture. It's more humble and relational than 'competence.'" },
  { domain: "Social & Cultural Diversity", question: "When counseling someone from a culture unfamiliar to the counselor, what is the most ethical approach?", options: ["A) Pretend to have knowledge", "B) Decline the client immediately", "C) Show genuine curiosity, ask respectful questions, seek education, and acknowledge knowledge limits", "D) Use only generic counseling approaches"], correct: 2, explanation: "Ethical practice involves acknowledging knowledge limits, inviting clients to share cultural context, seeking supervision and education, and approaching with humble respect for the client's expertise." },
  { domain: "Social & Cultural Diversity", question: "The concept of 'cultural brokers' or 'culture guides' in counseling refers to:", options: ["A) Counselors claiming to know all about a culture", "B) Community members or clients themselves helping counselors understand cultural context", "C) Only paid consultants", "D) Official government positions"], correct: 1, explanation: "Cultural brokers may be community members, clients, or consultants helping counselors understand cultural norms and dynamics. Respecting clients as experts about their own culture honors cultural knowledge." },
  { domain: "Social & Cultural Diversity", question: "When working with clients who have experienced discrimination or oppression, which counseling focus is most important?", options: ["A) Ignoring the discrimination to maintain positivity", "B) Blaming the client for discrimination they've experienced", "C) Validating their experience, exploring impact, and addressing trauma and systemic barriers", "D) Only focusing on individual coping without addressing systemic issues"], correct: 2, explanation: "Affirming therapy validates clients' experiences of discrimination, explores psychological impact, addresses trauma, and acknowledges systemic barriers. This differs from victim-blaming or ignoring reality." },
  { domain: "Social & Cultural Diversity", question: "The strengths-based approach in counseling with diverse clients emphasizes which aspect?", options: ["A) Only pathology and problems", "B) Cultural strengths, resilience, and adaptive strategies clients and communities have developed", "C) Ignoring challenges", "D) Only individual characteristics"], correct: 1, explanation: "Strengths-based approaches recognize cultural strengths—extended family systems, spirituality, community ties, resilience developed through adversity. These complement addressing challenges." },
  { domain: "Social & Cultural Diversity", question: "Cultural adaptation of counseling interventions for diverse clients involves:", options: ["A) Using identical interventions for all cultural groups", "B) Modifying interventions to fit clients' cultural worldviews while maintaining evidence-based principles", "C) Creating entirely different theories for each culture", "D) Never adapting anything"], correct: 1, explanation: "Cultural adaptation involves respecting cultural worldviews while implementing evidence-based interventions. This might mean adjusting pacing, language, involving family, or connecting to spiritual practices." },
  { domain: "Social & Cultural Diversity", question: "When a client's cultural values seem to contradict mental health goals (e.g., family obligation vs. individual autonomy), the counselor should:", options: ["A) Insist on the counselor's values", "B) Explore both values, understand the client's perspective, and collaborate on an approach respecting both", "C) Blame the culture for the problem", "D) Assume the client is confused"], correct: 1, explanation: "Value conflicts require collaborative exploration. Counselors can help clients integrate cultural values with mental health goals, rather than forcing a choice between them." },
  { domain: "Social & Cultural Diversity", question: "The concept of 'code-switching' in diverse populations refers to which communication behavior?", options: ["A) Changing one's entire identity", "B) Changing communication style, language, or behavior to fit different social contexts", "C) Being dishonest or fake", "D) Speaking multiple languages simultaneously"], correct: 1, explanation: "Code-switching—adapting communication for different contexts—is a normal adaptation skill. Many marginalized individuals code-switch to navigate majority spaces. It's not dishonesty but adaptive flexibility." },
  { domain: "Social & Cultural Diversity", question: "Understanding code-switching helps counselors recognize that clients' different presentations in different contexts is:", options: ["A) A sign of mental illness", "B) Dishonesty or inauthenticity", "C) A normal, often necessary adaptive skill", "D) Only something minorities experience"], correct: 2, explanation: "Code-switching is a normal adaptive skill, not pathology. Counselors should recognize its utility while also exploring whether code-switching creates stress or identity fragmentation requiring attention." },
  { domain: "Social & Cultural Diversity", question: "When counseling a client from a collectivist culture, which therapeutic goal modification might be appropriate?", options: ["A) Emphasizing complete independence", "B) Ignoring family and community relationships", "C) Including family in treatment and emphasizing harmony and community welfare alongside individual goals", "D) Telling the client to abandon cultural values"], correct: 2, explanation: "Collectivist-oriented counseling might include family sessions, emphasize community relationships, and frame goals around family or group benefit. This respects cultural values while supporting mental health." },
  { domain: "Social & Cultural Diversity", question: "The role of family in mental health across cultures is best understood through which lens?", options: ["A) Family is equally important everywhere", "B) Family is irrelevant to mental health", "C) Family structure, involvement, and emotional expression vary significantly across cultures", "D) Only Western nuclear families matter"], correct: 2, explanation: "Family roles, decision-making authority, emotional expressiveness, and intergenerational relationships vary across cultures. Extended family systems are primary in many non-Western cultures." },
  { domain: "Social & Cultural Diversity", question: "When a client's family or community would disapprove of counseling, what ethical stance is most appropriate?", options: ["A) Tell the client not to come", "B) Understand the cultural context while supporting the client's right to seek help", "C) Require family permission", "D) Dismiss the client's cultural concerns"], correct: 1, explanation: "Some cultures stigmatize mental health services or prefer family-based solutions. Counselors should acknowledge this cultural reality while supporting clients' autonomy and access to help." },
  { domain: "Social & Cultural Diversity", question: "The concept of 'individualism-collectivism' exists on a spectrum rather than as fixed categories. This means:", options: ["A) The concept is useless", "B) All individuals within a culture are identical", "C) Individuals and cultures vary in both individualistic and collectivistic tendencies", "D) Some cultures are purely individualistic"], correct: 2, explanation: "While cultures may lean more individualistic or collectivistic, individuals within cultures vary, and most people hold both orientations. Context also affects which orientation dominates." },
  { domain: "Social & Cultural Diversity", question: "When a client reports experiencing 'susto' (fright) or other culture-bound syndromes, the counselor should:", options: ["A) Dismiss it as not a real disorder", "B) Only diagnose Western diagnostic categories", "C) Understand the cultural meaning while assessing mental health impact and providing culturally informed treatment", "D) Assume it's spiritual possession"], correct: 2, explanation: "Culture-bound syndromes have meaning within their cultural context and real psychological impact. Counselors should understand the cultural meaning while also assessing symptoms and providing appropriate intervention." },
  { domain: "Social & Cultural Diversity", question: "The relationship between culture and mental health diagnosis most accurately reflects which understanding?", options: ["A) Mental illness is identical across all cultures", "B) Culture shapes how distress is experienced, expressed, and understood", "C) Mental illness doesn't exist in non-Western cultures", "D) Diagnosis should ignore cultural context"], correct: 1, explanation: "Culture affects symptom expression (e.g., somatic vs. emotional), meaning attributed to symptoms, and help-seeking behavior. Culturally informed diagnosis recognizes these variations." },
  { domain: "Social & Cultural Diversity", question: "When a client describes symptoms that could fit multiple interpretations (mental illness, spiritual crisis, grief), what approach is most appropriate?", options: ["A) Assume mental illness immediately", "B) Assume spiritual crisis", "C) Collaboratively explore meanings and impacts with the client's cultural context", "D) Only rely on diagnostic manuals"], correct: 2, explanation: "Multiple valid interpretations may coexist. Counselors should explore with the client which meaning fits their worldview and address both psychological and spiritual/cultural dimensions." },
  { domain: "Social & Cultural Diversity", question: "The 'cultural formulation' in assessment involves which process?", options: ["A) Assigning a diagnosis quickly", "B) Systematically understanding the client's cultural identity, cultural explanations of illness, and cultural features of the relationship", "C) Ignoring cultural factors", "D) Only for anthropologists"], correct: 1, explanation: "Cultural formulation (included in DSM-5) involves systematically exploring cultural identity, relationships, explanations for symptoms, and cultural features affecting treatment. It supplements diagnosis." },
  { domain: "Social & Cultural Diversity", question: "Regarding communication preferences, which cultural consideration is most important in counseling?", options: ["A) All cultures communicate identically", "B) Direct vs. indirect communication, appropriateness of emotional expression, and formality levels vary culturally", "C) Only language spoken matters", "D) Communication style is irrelevant"], correct: 1, explanation: "Cultures differ significantly in communication directness, emotional expression norms, formality, and expressiveness. What's respectful or honest in one culture may be rude in another." },
  { domain: "Social & Cultural Diversity", question: "When a client uses indirect communication (common in high-context cultures), a counselor should:", options: ["A) Insist on direct statements", "B) Interpret indirect communication as evasiveness", "C) Develop patience and attunement to subtle meanings and nonverbals", "D) Assume the client is being dishonest"], correct: 2, explanation: "Indirect communication is culturally normative in many contexts. Counselors should develop skill in reading subtle cues, respecting relationship-building needs, and avoiding pressure for premature disclosure." },
  { domain: "Social & Cultural Diversity", question: "The concept of 'honor' and 'shame' varies across cultures and affects counseling how?", options: ["A) These concepts don't matter in modern counseling", "B) Honor-based cultures prioritize family/community reputation; shame-based cultures prioritize internal guilt", "C) All cultures are identical regarding honor and shame", "D) These concepts only exist in Asian cultures"], correct: 1, explanation: "Some cultures are honor-based (prioritizing reputation and family standing); others emphasize individual shame/guilt. Counselors must understand whether clients' concerns relate to shame or honor." },
  { domain: "Social & Cultural Diversity", question: "When a client is concerned about family honor or community reputation, what therapeutic stance is appropriate?", options: ["A) Dismiss these concerns as superficial", "B) Prioritize individual needs exclusively", "C) Understand and respect these concerns while exploring how to balance them with individual needs", "D) Tell the client their culture is wrong"], correct: 2, explanation: "In honor-oriented cultures, reputation and family standing are legitimate concerns. Counselors can help clients navigate between individual needs and family/community concerns." },
  { domain: "Social & Cultural Diversity", question: "The concept of 'face' (particularly in Asian cultures) relates most closely to which aspect?", options: ["A) Physical appearance", "B) Dignity, honor, and appropriate social functioning", "C) Only business interactions", "D) Deception"], correct: 1, explanation: "'Face' refers to reputation, dignity, and social standing. Counselors must avoid causing clients to 'lose face' and understand therapeutic approaches that maintain dignity and respect." },
  { domain: "Social & Cultural Diversity", question: "When providing feedback or addressing concerns with a client from a culture emphasizing 'face,' how should the counselor approach it?", options: ["A) Give harsh feedback directly", "B) Never address problems to avoid loss of face", "C) Address issues privately, respectfully, and carefully, maintaining dignity", "D) Only praise, never critique"], correct: 2, explanation: "Counselors should address concerns constructively while protecting dignity. Private settings, gentle approaches, and framing feedback as collaboration help maintain face and therapeutic alliance." },
  { domain: "Social & Cultural Diversity", question: "Time orientation—whether a culture emphasizes past, present, or future—affects counseling through:", options: ["A) Having no impact", "B) Influencing goal-setting, planning, and how clients relate to problems", "C) Only affecting scheduling", "D) Determining the length of therapy"], correct: 1, explanation: "Past-oriented cultures emphasize tradition and history; present-oriented cultures emphasize immediate experience; future-oriented cultures emphasize planning. This affects therapy goals, pacing, and problem interpretation." },
  { domain: "Social & Cultural Diversity", question: "When working with a past-oriented client on future-focused goals, what approach is most effective?", options: ["A) Demand they focus on the future", "B) Ignore their past orientation", "C) Connect future goals to past values and traditions", "D) Assume they lack ambition"], correct: 2, explanation: "Counselors can honor past orientation by connecting future goals to cultural history and values. This bridges perspectives and increases client engagement with future-oriented counseling." },
  { domain: "Social & Cultural Diversity", question: "The concept of 'locus of responsibility' particularly applies to clients who have experienced discrimination by addressing which understanding?", options: ["A) Whether they blame themselves for discrimination", "B) Only financial responsibility", "C) Whether systemic oppression is recognized alongside individual factors", "D) Only personal guilt"], correct: 2, explanation: "Clients from oppressed groups may internalize blame for systemic barriers. Counselors must help distinguish between individual responsibility and systemic oppression, reducing inappropriate self-blame." },
  { domain: "Social & Cultural Diversity", question: "Cultural grief and loss take particular importance in counseling with which populations?", options: ["A) Only refugees", "B) Only immigrants", "C) Refugees, immigrants, and people displaced by oppression experience multiple losses", "D) Loss doesn't vary by culture"], correct: 2, explanation: "Migrants, refugees, and displaced people experience profound losses: homeland, relationships, identity, social status. Counselors should explicitly address cultural grief alongside processing adjustment." },
  { domain: "Social & Cultural Diversity", question: "When counseling someone from a culture where emotional expression is modulated differently, how should the counselor respond?", options: ["A) Require emotional catharsis", "B) Assume lack of emotion means lack of concern", "C) Understand different expression norms while assessing actual emotional experience", "D) Tell them to express like the majority culture"], correct: 2, explanation: "Some cultures value emotional restraint; others value expressiveness. Counselors should not equate quiet demeanor with lack of emotion and should respect cultural expression norms." },
  { domain: "Social & Cultural Diversity", question: "The role of elders and authority figures in problem-solving varies culturally. Counselors should:", options: ["A) Always privilege individual therapy over family", "B) Always involve elders regardless of client preference", "C) Explore the client's cultural context regarding authority and decision-making", "D) Assume Western individualism is universal"], correct: 2, explanation: "In some cultures, consulting elders or authority figures is essential; in others, it's intrusive. Counselors should explore with clients which approach fits their cultural values." },
  { domain: "Social & Cultural Diversity", question: "Gender roles and expectations vary significantly across cultures. In counseling, this means:", options: ["A) All cultures have identical gender roles", "B) Gender roles don't matter to mental health", "C) Counselors must understand cultural gender expectations and help clients navigate them", "D) Counselors should impose Western gender norms"], correct: 2, explanation: "Gender roles, authority, and expression differ across cultures. Counselors should understand cultural context while supporting clients' agency to define their own gender identity and roles." },
  { domain: "Social & Cultural Diversity", question: "The concept of 'machismo' (masculinity emphasis) in some Latin American cultures requires counselors to:", options: ["A) Criticize the cultural value", "B) Understand how it shapes behavior and identity while helping men navigate changing roles", "C) Reinforce traditional gender roles", "D) Ignore cultural context"], correct: 1, explanation: "Cultural understanding includes recognizing values like machismo while helping clients explore how these affect their health, relationships, and identity in contemporary contexts." },
  { domain: "Social & Cultural Diversity", question: "Different cultural approaches to mental health—from holistic Indigenous models to Western biomedical models—require counselors to:", options: ["A) Adopt only one model", "B) Devalue non-Western approaches", "C) Understand multiple healing traditions and collaborate with clients' preferred approaches", "D) Argue for Western superiority"], correct: 2, explanation: "Many cultures use complementary approaches: traditional healers, herbs, spiritual practices alongside counseling. Respectful practice involves understanding and integrating these when appropriate." },
  { domain: "Social & Cultural Diversity", question: "When a client prefers consulting a traditional healer or spiritual leader instead of pursuing counseling, the ethical counselor should:", options: ["A) Refuse to see the client", "B) Criticize their choice", "C) Respect the choice while remaining available and potentially collaborating if appropriate", "D) Convince them counseling is superior"], correct: 2, explanation: "Respecting client autonomy means accepting their healing choices. Counselors can potentially collaborate with traditional healers if the client consents and it serves the client's welfare." }
];

// Export for use
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { ETHICS_QUESTIONS, DIVERSITY_QUESTIONS };
}
